/* SQL ID : DashboardDAO.widgetStngSelect 설 명 : 위젯 변경 사용자용 조회 */ SELECT TLWU.ORG_ID , TLWU.USER_ID , TLWU.WIDGET_ID , TLWU.WIDGETNM , TLWU.WIDGET_USER_STNG_CTS AS WIDGET_STNG_CTS FROM TB_LMS_WIDGET_USE TLWU WHERE 1=1
AND USER_ID = #{userId}
ORDER BY TO_NUMBER(REGEXP_SUBSTR(TLWU.WIDGET_ID, '[0-9]+'))

/* SQL ID : DashboardDAO.widgetStngPopView 설 명 : 상단 위젯 설정 팝업(위젯) */ SELECT TLWU.WIDGET_USER_STNG_CTS AS WIDGET_STNG_CTS FROM TB_LMS_WIDGET_USE TLWU WHERE 1=1
AND USER_ID = #{userId}
ORDER BY TO_NUMBER(REGEXP_SUBSTR(TLWU.WIDGET_ID, '[0-9]+'))

/* SQL ID : DashboardDAO.widgetStngColrPopView 설 명 : 상단 위젯 설정 팝업(색상) */ SELECT TLWU.WIDGET_USER_STNG_CTS AS WIDGET_STNG_CTS FROM TB_LMS_WIDGET_USE TLWU WHERE 1=1
AND USER_ID = #{userId}
ORDER BY TO_NUMBER(REGEXP_SUBSTR(TLWU.WIDGET_ID, '[0-9]+'))
